<script setup lang="ts">
import {computed,inject,reactive,ref,shallowRef,watch} from 'vue'
import type {ApiError} from '@/core/http'
import {deviceDataSourceContextKey,deviceDataInputStreams} from './device-data-source-context'
import ReferenceIcon from '@/ui/ReferenceIcon.vue'
import DataOperationsEditor from './DataOperationsEditor.vue'
import DataPropertyFunctionDialog from './DataPropertyFunctionDialog.vue'
import type {DataPropertyFunction} from './data-property-preview-api'
import {validateDataOperationsContext,type DataOperations} from './data-operations-api'
import {dataStreamTemplate,type DataStreamItem} from '../device-types/data-stream-publication-api'
import GatewayDataParserDialog from './GatewayDataParserDialog.vue'
import {normalizeGatewayDataParser,type GatewayDataParser} from './gateway-data-parser-api'
import DataDownlinkFunctionDialog from './DataDownlinkFunctionDialog.vue'
import {type DataDownlinkFunction} from './data-downlink-function-api'
import {normalizeSubdeviceModbusRtuParser,type SubdeviceModbusRtuParser} from './subdevice-modbus-rtu-parser-api'
import ModbusRtuParserDialog from './ModbusRtuParserDialog.vue'
import {normalizeModbusRtuParser,type ModbusRtuParser} from './modbus-rtu-parser-api'
import RulePreprocessFunctionsEditor from './RulePreprocessFunctionsEditor.vue'
import RuleTagsEditor from './RuleTagsEditor.vue'
import type {RuleTagDraft} from './rule-tag-draft'
import RuleTriggerSelector from './RuleTriggerSelector.vue'
import RuleConditionGroupEditor from './RuleConditionGroupEditor.vue'
import {newConditionGroup,newFunction,dataReportFunctionSource,ruleKindLabels,type PreprocessKind,type RuleKind,type FunctionDraft} from './rule-builder-draft'
import {makePreprocessCreationDraft,makeTypeDataCreationDraft,makeTypeNativeDataCreationDraft,makeTypeDownlinkCreationDraft,makeTypeGatewayDataCreationDraft,makeTypeSubdeviceNativeDataCreationDraft,makeTypeDataOperationsCreationDraft,upgradeSingleDataOperation,readRuleConditionDraft,preprocessConditionJson,type PreprocessCreationDraft} from './preprocess-version-editor'
import {sourceIds,sourceNames,type RuleSourceSelection} from './rule-source-selection'
import {sourceContract} from './rule-source-api'
import {definitionUuid} from './device-task-definition-port'
import type {PropertyOperationsDraft} from './property-operations-draft'
/** 父层必须以真实设备/项目/身份范围给scopeKey；本控件只发领域意图，不调用HTTP或假称写成功。 */
const props=defineProps<{scopeKey:string;projectId?:string;deviceId?:string;deviceName?:string;source?:{kind:'DEVICE'|'DEVICE_TYPE';referenceId:string;name:string};sourceSelection?:RuleSourceSelection;disabled?:boolean;rejectedAttempt?:string;dataStreams?:readonly DataStreamItem[];initialName?:string;initialKind?:PreprocessKind|'DATA_RPT';initialFilterJson?:string;initialStreamIdentifier?:string;externalFirstStep?:boolean;sourceDeviceKind?:string;sourcePayloadProtocol?:string;dataStreamsError?:string;gatewayDataAvailable?:boolean;subdeviceAddressAllowed?:boolean}>()
const deviceDataContext=inject(deviceDataSourceContextKey,undefined),dataSourceAvailable=computed(()=>props.source?.kind==='DEVICE_TYPE'||props.sourceSelection?.kind==='DEVICE'&&!!deviceDataContext?.value),dataContexts=computed(()=>deviceDataContext?.value?.members.map(member=>{const stream=member.streams.find(stream=>stream.identifier===form.streamIdentifier);return{deviceKind:member.profile.type.deviceKind,payloadProtocol:member.profile.type.payloadProtocol,streamFormat:stream?.format??'',streamTemplate:stream?dataStreamTemplate(stream):undefined}}))
const origin=computed(()=>props.sourceSelection?{kind:props.sourceSelection.kind,referenceId:props.sourceSelection.members.length===1?props.sourceSelection.members[0]!.referenceId:'',name:sourceNames(props.sourceSelection)}:props.source??{kind:'DEVICE' as const,referenceId:props.deviceId??'',name:props.deviceName??''})
const emit=defineEmits<{'create-sources':[intent:{scopeKey:string;source:RuleSourceSelection;attemptId:string;draft:PreprocessCreationDraft}];'create-source':[intent:{scopeKey:string;source:{kind:'DEVICE'|'DEVICE_TYPE';referenceId:string};attemptId:string;draft:PreprocessCreationDraft}];submit:[intent:{scopeKey:string;deviceId:string;attemptId:string;draft:PreprocessCreationDraft}];cancel:[];previous:[];denied:[cause:ApiError];locked:[value:boolean];'select-kind':[value:RuleKind|undefined]}>()
const dataFormats=computed<readonly string[]>(()=>props.sourceDeviceKind==='SUB_DEVICE'?['HEX']:['TEXT','HEX','JSON'])
const dataOperations=shallowRef<DataOperations>(),stagedOperations=shallowRef<DataOperations>(),operationsLocked=ref(false),propertyShown=ref(false),propertyBusy=ref(false),propertyCandidate=ref<string>()
const operations=computed(()=>dataOperations.value??stagedOperations.value),sourceKind=computed(()=>props.sourceDeviceKind??(props.subdeviceAddressAllowed?'SUB_DEVICE':props.gatewayDataAvailable?'GATEWAY':'DIRECT')),sourceProtocol=computed(()=>props.sourcePayloadProtocol??(props.gatewayDataAvailable?'STANDARD_GATEWAY':'STANDARD'))
const selectedDataStream=computed(()=>props.dataStreams?.find(stream=>stream.identifier===form.streamIdentifier))
const kinds=computed<readonly RuleKind[]>(()=>origin.value.kind==='DEVICE_TYPE'||dataSourceAvailable.value?['ATTRS_RPT_PREPROC','ATTRS_PUSH_PREPROC','DATA_RPT']:['ATTRS_RPT_PREPROC','ATTRS_PUSH_PREPROC'])
const form=reactive({name:'',description:'',kind:undefined as PreprocessKind|'DATA_RPT'|undefined,streamIdentifier:'',filter:newConditionGroup(),functions:[] as FunctionDraft[],propertyOperations:undefined as PropertyOperationsDraft|undefined,tags:[] as RuleTagDraft[]})
const subdeviceNativeParser=shallowRef<SubdeviceModbusRtuParser>(),nativeParser=shallowRef<ModbusRtuParser>(),nativeShown=ref(false),nativeBusy=ref(false),actionPickerShown=ref(false)
const downlink=shallowRef<DataDownlinkFunction>(),downlinkShown=ref(false),downlinkBusy=ref(false)
const gatewayParser=shallowRef<GatewayDataParser>(),gatewayShown=ref(false),gatewayBusy=ref(false)
const selectedNative=computed(()=>subdeviceNativeParser.value??nativeParser.value)
const hasOperation=computed(()=>!!dataOperations.value||!!subdeviceNativeParser.value||!!gatewayParser.value||!!nativeParser.value||!!downlink.value||!!form.functions.length)
const sourceEditing=ref(false),functionsOpen=ref(true)
const step=ref(props.externalFirstStep?2:1),error=ref(''),attempt=ref<string>(),baseBlocked=computed(()=>!!props.disabled||!!attempt.value),editorDisabled=computed(()=>baseBlocked.value||nativeShown.value||downlinkShown.value||gatewayShown.value||actionPickerShown.value||operationsLocked.value||propertyShown.value),blocked=computed(()=>editorDisabled.value||sourceEditing.value)
watch(()=>form.kind,value=>emit('select-kind',value),{immediate:true})
watch([attempt,nativeShown,downlinkShown,gatewayShown,actionPickerShown,operationsLocked,propertyShown,sourceEditing],()=>emit('locked',!!attempt.value||nativeShown.value||downlinkShown.value||gatewayShown.value||actionPickerShown.value||operationsLocked.value||propertyShown.value||sourceEditing.value),{immediate:true,flush:'sync'})
watch(()=>props.initialName,value=>{if(props.externalFirstStep&&!attempt.value)form.name=value??''})
watch(()=>props.initialFilterJson,value=>{if(props.externalFirstStep&&!attempt.value)form.filter=value===undefined?newConditionGroup():readRuleConditionDraft(value)})
watch(()=>props.rejectedAttempt,value=>{if(value&&value===attempt.value)attempt.value=undefined})
watch([()=>props.scopeKey,()=>origin.value.kind,()=>origin.value.referenceId,()=>props.sourceSelection?sourceIds(props.sourceSelection).join(','):''],()=>{sourceEditing.value=false;functionsOpen.value=true;dataOperations.value=initialDataOperations(props.initialKind);stagedOperations.value=undefined;operationsLocked.value=false;propertyShown.value=false;propertyCandidate.value=undefined;propertyBusy.value=false;form.name=props.initialName??'';form.description='';form.kind=props.initialKind&&kinds.value.includes(props.initialKind)?props.initialKind:undefined;form.streamIdentifier=props.externalFirstStep&&props.initialKind==='DATA_RPT'?props.initialStreamIdentifier??'':'';form.filter=props.initialFilterJson===undefined?newConditionGroup():readRuleConditionDraft(props.initialFilterJson);form.functions=[];form.propertyOperations=undefined;nativeParser.value=undefined;subdeviceNativeParser.value=undefined;downlink.value=undefined;gatewayParser.value=undefined;gatewayShown.value=false;gatewayBusy.value=false;downlinkShown.value=false;downlinkBusy.value=false;nativeShown.value=false;nativeBusy.value=false;actionPickerShown.value=false;form.tags=[];step.value=props.externalFirstStep?2:1;error.value='';attempt.value=undefined},{immediate:true})
/** 外部第一步与本地类型选择使用相同的组合初始化，不把网关/子设备回落为旧单项合同。 */
function initialDataOperations(value:RuleKind|undefined):DataOperations|undefined{return value==='DATA_RPT'&&kinds.value.includes(value)&&['GATEWAY','SUB_DEVICE'].includes(sourceKind.value)?{profile:'DATA_OPERATIONS_V1',operations:[]}:undefined}
function kind(value:RuleKind){if(form.kind===value)return;if(!blocked.value&&(value==='ATTRS_RPT_PREPROC'||value==='ATTRS_PUSH_PREPROC'||value==='DATA_RPT'&&dataSourceAvailable.value)){if(form.kind!==value){form.functions=[];form.propertyOperations=undefined;nativeParser.value=undefined;subdeviceNativeParser.value=undefined;downlink.value=undefined;gatewayParser.value=undefined}form.kind=value;dataOperations.value=initialDataOperations(value);stagedOperations.value=undefined;error.value=''}}
function validSource(){if(props.sourceSelection){sourceIds(props.sourceSelection);if(props.sourceSelection.members.some(row=>!row.name.trim())||props.source||props.deviceId||!props.scopeKey)throw new Error('来源设备不完整，请重新读取')}else if(!definitionUuid(origin.value.referenceId)||!origin.value.name.trim()||!!props.source&&!!props.deviceId||!props.scopeKey)throw new Error('来源设备不完整，请重新读取')}
function next(){
 if(blocked.value)return
 try{if(!form.name.trim()||form.name.trim().length>128)throw new Error('请输入规则名称（最多128字）');if(!form.kind)throw new Error('请选择属性预处理类型');validSource();if(form.kind==='ATTRS_RPT_PREPROC')preprocessConditionJson(form.filter);if(form.kind==='DATA_RPT'&&!props.dataStreams?.some(x=>x.identifier===form.streamIdentifier&&dataFormats.value.includes(x.format)))throw new Error('请选择当前已发布的TEXT、HEX或JSON数据流');if(selectedNative.value&&selectedDataStream.value?.format!=='HEX')throw new Error('Modbus RTU解析仅支持已发布HEX数据流');step.value=2;error.value=''}catch(cause){error.value=cause instanceof Error?cause.message:'请补全规则设置'}
}
function submit(){
 if(blocked.value)return
 try{
  if(form.kind==='DATA_RPT'&&(!dataSourceAvailable.value||!props.dataStreams?.some(x=>x.identifier===form.streamIdentifier&&dataFormats.value.includes(x.format))))throw new Error('请选择当前已发布的TEXT、HEX或JSON数据流');if(subdeviceNativeParser.value&&(form.kind!=='DATA_RPT'||!props.subdeviceAddressAllowed||nativeParser.value||gatewayParser.value||downlink.value||form.functions.length))throw new Error('子设备Native须使用实际绑定地址');if(gatewayParser.value&&(form.kind!=='DATA_RPT'||!props.gatewayDataAvailable||subdeviceNativeParser.value||nativeParser.value||downlink.value||form.functions.length))throw new Error('请选择标准网关类型和一个云网关解析操作');if(nativeParser.value&&(form.kind!=='DATA_RPT'||gatewayParser.value||form.functions.length||selectedDataStream.value?.format!=='HEX'))throw new Error('Modbus RTU解析仅支持HEX数据流，且不能与属性函数同时配置');if(downlink.value&&(form.kind!=='DATA_RPT'||subdeviceNativeParser.value||gatewayParser.value||nativeParser.value||form.functions.length))throw new Error('仅能设置一个下行操作');if(dataOperations.value){if(!selectedDataStream.value)throw new Error('请选择当前已发布的数据流');for(const context of dataContexts.value??[{deviceKind:sourceKind.value,payloadProtocol:sourceProtocol.value,streamFormat:selectedDataStream.value.format,streamTemplate:dataStreamTemplate(selectedDataStream.value)}])validateDataOperationsContext(dataOperations.value,context)}const draft=dataOperations.value?makeTypeDataOperationsCreationDraft({...form,dataOperations:dataOperations.value}):subdeviceNativeParser.value?makeTypeSubdeviceNativeDataCreationDraft({...form,subdeviceNativeParser:subdeviceNativeParser.value}):gatewayParser.value?makeTypeGatewayDataCreationDraft({...form,gatewayParser:gatewayParser.value}):downlink.value?makeTypeDownlinkCreationDraft({...form,dataDownlink:downlink.value}):nativeParser.value?makeTypeNativeDataCreationDraft({...form,nativeParser:nativeParser.value}):form.kind==='DATA_RPT'?makeTypeDataCreationDraft(form):makePreprocessCreationDraft({...form,kind:form.kind});validSource()
  const attemptId=crypto.randomUUID();attempt.value=attemptId;error.value='';if(props.sourceSelection)emit('create-sources',{scopeKey:props.scopeKey,source:props.sourceSelection,attemptId,draft});else if(props.source)emit('create-source',{scopeKey:props.scopeKey,source:{kind:origin.value.kind,referenceId:origin.value.referenceId},attemptId,draft});else emit('submit',{scopeKey:props.scopeKey,deviceId:origin.value.referenceId,attemptId,draft})
 }catch(cause){error.value=cause instanceof Error?cause.message:'请补全预处理操作'}
}
function functionDenied(cause:ApiError){functionsOpen.value=false;form.functions=[];form.propertyOperations=undefined;form.description='';form.tags=[];form.name='';sourceEditing.value=false;emit('denied',cause)}
function adoptOperations(value:DataOperations){if(baseBlocked.value)return;dataOperations.value=value;stagedOperations.value=undefined;nativeParser.value=undefined;subdeviceNativeParser.value=undefined;gatewayParser.value=undefined;downlink.value=undefined;form.functions=[]}
function addOperation(){if(blocked.value||form.kind!=='DATA_RPT'||!hasOperation.value)return;try{stagedOperations.value=upgradeSingleDataOperation({nativeParser:nativeParser.value,subdeviceNativeParser:subdeviceNativeParser.value,gatewayParser:gatewayParser.value,dataDownlink:downlink.value,functions:form.functions},props.sourceSelection?.kind==='DEVICE'?deviceDataInputStreams(deviceDataContext?.value,sourceContract(props.sourceSelection),form.streamIdentifier):selectedDataStream.value?[selectedDataStream.value]:undefined)}catch(cause){error.value=cause instanceof Error?cause.message:'请先补全原操作'}}
function saveProperty(value:DataPropertyFunction){if(!baseBlocked.value&&!propertyBusy.value&&propertyShown.value&&(propertyCandidate.value!==undefined||form.functions.length===1)){form.functions=[{...(form.functions[0]??newFunction()),format:'COMMON_JS',source:value.source}];propertyShown.value=false;propertyCandidate.value=undefined}}
function closeProperty(){if(!propertyBusy.value){propertyShown.value=false;propertyCandidate.value=undefined}}
function editSingle(){if(blocked.value)return;if(gatewayParser.value)openGateway();else if(downlink.value)openDownlink();else if(selectedNative.value)openNative();else if(form.functions.length===1)propertyShown.value=true}
function removeSingle(){if(blocked.value)return;gatewayParser.value=undefined;downlink.value=undefined;nativeParser.value=undefined;subdeviceNativeParser.value=undefined;form.functions=[]}
const singleOperation=computed(()=>gatewayParser.value?{label:'云网关解析函数',glyph:'󰡱'}:downlink.value?{label:'向当前设备下发自定义数据',glyph:'󰿨'}:selectedNative.value?{label:'Modbus RTU 解析',glyph:'󰌗'}:form.functions.length?{label:'属性解析函数',glyph:'󰡱'}:undefined)
function openActionPicker(){if(blocked.value||form.kind!=='DATA_RPT'||hasOperation.value)return;if(!selectedDataStream.value){error.value='当前设备来源未共同发布该数据流，请返回检查数据流标识符';return}actionPickerShown.value=true}
function closeActionPicker(){if(!baseBlocked.value)actionPickerShown.value=false}
function chooseAction(action:'NATIVE'|'PROPERTY'|'DOWNLINK'|'GATEWAY'){
 if(baseBlocked.value||!actionPickerShown.value||hasOperation.value||form.kind!=='DATA_RPT')return
 if(action==='GATEWAY'){if(!props.gatewayDataAvailable||!dataSourceAvailable.value||!definitionUuid(props.projectId))return;gatewayShown.value=true}else if(action==='DOWNLINK'){if(!dataSourceAvailable.value||!definitionUuid(props.projectId))return;downlinkShown.value=true}else if(action==='NATIVE'){if(selectedDataStream.value?.format!=='HEX')return;openNative();if(!nativeShown.value)return}else{propertyCandidate.value=dataReportFunctionSource;propertyShown.value=true}
 actionPickerShown.value=false
}
function openNative(){if(!baseBlocked.value&&!nativeShown.value&&form.kind==='DATA_RPT'&&dataSourceAvailable.value&&definitionUuid(props.projectId)&&selectedDataStream.value?.format==='HEX'&&!form.functions.length&&!downlink.value&&!gatewayParser.value)nativeShown.value=true}
function closeNative(){if(!nativeBusy.value)nativeShown.value=false}
function saveNative(value:ModbusRtuParser|SubdeviceModbusRtuParser){
 if(baseBlocked.value||nativeBusy.value||!nativeShown.value||gatewayParser.value||downlink.value||form.functions.length||selectedDataStream.value?.format!=='HEX')return
 if(value.useSubdeviceAddress){if(!props.subdeviceAddressAllowed)return;subdeviceNativeParser.value=normalizeSubdeviceModbusRtuParser(value);nativeParser.value=undefined}
 else{if(props.subdeviceAddressAllowed)return;nativeParser.value=normalizeModbusRtuParser(value);subdeviceNativeParser.value=undefined}
 nativeShown.value=false
}
function removeNative(){if(!blocked.value){nativeParser.value=undefined;subdeviceNativeParser.value=undefined}}

function openDownlink(){if(!blocked.value&&form.kind==='DATA_RPT'&&!selectedNative.value&&!gatewayParser.value&&!form.functions.length)downlinkShown.value=true}
function closeDownlink(){if(!downlinkBusy.value)downlinkShown.value=false}
function saveDownlink(value:DataDownlinkFunction){if(!baseBlocked.value&&!downlinkBusy.value&&downlinkShown.value&&!selectedNative.value&&!gatewayParser.value&&!form.functions.length){downlink.value=value;downlinkShown.value=false}}
function removeDownlink(){if(!blocked.value)downlink.value=undefined}
function openGateway(){if(!blocked.value&&props.gatewayDataAvailable&&gatewayParser.value&&!selectedNative.value&&!downlink.value&&!form.functions.length)gatewayShown.value=true}
function closeGateway(){if(!gatewayBusy.value)gatewayShown.value=false}
function saveGateway(value:GatewayDataParser){if(!baseBlocked.value&&!gatewayBusy.value&&gatewayShown.value&&props.gatewayDataAvailable&&!selectedNative.value&&!downlink.value&&!form.functions.length){gatewayParser.value=normalizeGatewayDataParser(value);gatewayShown.value=false}}
function removeGateway(){if(!blocked.value)gatewayParser.value=undefined}
function cancel(){if(!editorDisabled.value){functionsOpen.value=false;sourceEditing.value=false;emit('cancel')}}
/** 返回第一步只清操作，保留当前业务来源的基本字段、描述与标签；在途和未知意图不可退回。 */
function previous(){if(blocked.value||step.value!==2)return;form.functions=[];form.propertyOperations=undefined;nativeParser.value=undefined;subdeviceNativeParser.value=undefined;gatewayParser.value=undefined;downlink.value=undefined;dataOperations.value=undefined;stagedOperations.value=undefined;propertyCandidate.value=undefined;if(props.externalFirstStep)emit('previous');else step.value=1;error.value=''}
</script>
<template><section class="device-rule-preprocess-builder" :aria-busy="!!attempt">
 <el-form label-position="top" :disabled="baseBlocked" @submit.prevent="step===1?next():submit()">
  <div v-if="step===1" class="builder-step" data-step="1">
   <el-form-item label="规则名称"><el-input v-model="form.name" aria-label="规则名称" maxlength="128"/></el-form-item>
   <h3>设置规则类型</h3><RuleTriggerSelector :model-value="form.kind" :kinds="kinds" :disabled="blocked" @update:model-value="kind"/>
   <h3>设置设备来源</h3><el-form-item :label="origin.kind==='DEVICE_TYPE'?'来源设备类型':'来源设备'"><el-input :model-value="origin.name" :aria-label="origin.kind==='DEVICE_TYPE'?'来源设备类型':'来源设备'" readonly/></el-form-item>
   <template v-if="form.kind==='DATA_RPT'"><el-form-item label="数据流"><el-select v-model="form.streamIdentifier" aria-label="DATA业务流" :disabled="blocked"><el-option v-for="stream in dataStreams??[]" :key="stream.identifier" :value="stream.identifier" :label="stream.name+' · '+stream.identifier+' · '+stream.format" :disabled="!dataFormats.includes(stream.format)"/></el-select></el-form-item><p role="note">选择已发布的TEXT、HEX或JSON数据流，设置数据上报后的操作；Modbus RTU解析使用HEX数据流。</p><p v-if="dataStreamsError" role="alert">{{dataStreamsError}}</p><p v-else-if="!dataStreams?.length">当前类型没有已发布数据流，请先在DATA中发布。</p></template>
   <RuleConditionGroupEditor v-if="form.kind==='ATTRS_RPT_PREPROC'" v-model="form.filter" :disabled="blocked" :number-text-limit="1024"/>
  </div>
  <div v-else class="builder-step" data-step="2">
   <p v-if="externalFirstStep&&form.name.trim()" class="builder-summary"><strong>{{form.name.trim()}}</strong></p>
   <p v-if="!externalFirstStep" class="builder-summary"><strong>{{form.name.trim()}}</strong><span>{{form.kind?ruleKindLabels[form.kind].label:''}}</span><span>{{origin.name}}</span><span v-if="form.kind==='DATA_RPT'">{{form.streamIdentifier}} · {{selectedDataStream?.format}}</span></p>
   <template v-if="externalFirstStep&&form.kind==='DATA_RPT'&&initialStreamIdentifier===undefined"><el-form-item label="数据流"><el-select v-model="form.streamIdentifier" aria-label="DATA业务流" :disabled="blocked"><el-option v-for="stream in dataStreams??[]" :key="stream.identifier" :value="stream.identifier" :label="stream.name+' · '+stream.identifier+' · '+stream.format" :disabled="!dataFormats.includes(stream.format)"/></el-select></el-form-item><p v-if="dataStreamsError" role="alert">{{dataStreamsError}}</p><p v-else-if="!dataStreams?.length">当前类型没有已发布数据流，请先在DATA中发布。</p></template>
   <RuleConditionGroupEditor v-if="externalFirstStep&&initialFilterJson===undefined&&form.kind==='ATTRS_RPT_PREPROC'" v-model="form.filter" :disabled="blocked" :number-text-limit="1024"/>
   <h3>操作</h3><p v-if="form.kind==='DATA_RPT'" class="function-help">操作是当规则条件触发后执行的活动，一个规则可以设置多种操作。 <a href="https://www.thingscloud.xyz/docs/guide/tasks/attrs-push.html" target="_blank" rel="noopener noreferrer">了解详情</a></p><DataOperationsEditor v-if="form.kind==='DATA_RPT'&&operations&&selectedDataStream&&projectId" :model-value="operations" :project-id="projectId" :type-id="origin.kind==='DEVICE_TYPE'?origin.referenceId:''" :scope-key="scopeKey" :stream="selectedDataStream" :streams="dataStreams??[]" :device-kind="sourceKind" :payload-protocol="sourceProtocol" :source-contexts="dataContexts" :disabled="baseBlocked" :auto-add="!!stagedOperations" @update:model-value="adoptOperations" @cancel-add="stagedOperations=undefined" @locked="operationsLocked=$event"/><template v-if="!operations">
   <template v-if="form.kind==='DATA_RPT'"><el-table :data="singleOperation?[singleOperation]:[]" :show-header="false" empty-text="暂无数据" class="data-operation-table"><el-table-column prop="label"/><el-table-column width="50"><template #default><el-button circle size="small" :disabled="blocked" aria-label="编辑操作" @click="editSingle"><ReferenceIcon glyph="󰏫"/></el-button></template></el-table-column><el-table-column width="50"><template #default><el-button circle size="small" type="danger" :disabled="blocked" aria-label="移除操作" @click="removeSingle"><ReferenceIcon glyph="󰆴"/></el-button></template></el-table-column></el-table><el-button :disabled="blocked" @click="hasOperation?addOperation():openActionPicker()">添加操作</el-button></template>
   <RulePreprocessFunctionsEditor v-else-if="functionsOpen" v-model="form.functions" v-model:property-operations="form.propertyOperations" :source="sourceSelection??origin" :scope-key="scopeKey" :kind="form.kind==='DATA_RPT'?undefined:form.kind" :project-id="projectId" :disabled="editorDisabled" @busy="sourceEditing=$event" @denied="functionDenied"/></template>
   <el-form-item label="规则描述（选填）" class="description"><el-input v-model="form.description" aria-label="规则描述" type="textarea" maxlength="512" :rows="3"/></el-form-item>
   <RuleTagsEditor v-model="form.tags" :disabled="blocked"/>
  </div>
 </el-form>
 <el-alert v-if="error" :title="error" type="warning" :closable="false"/>
 <p v-if="attempt" class="tl-muted" role="status">创建结果待核对，请勿重复创建。</p>
 <footer class="builder-actions"><el-button :disabled="editorDisabled" @click="cancel">取消</el-button><el-button v-if="step===2" :disabled="blocked" @click="previous">上一步</el-button><el-button v-if="step===1" type="primary" :disabled="blocked" @click="next">下一步</el-button><el-button v-else type="primary" :disabled="blocked" @click="submit">创建</el-button></footer>
